fn days_to_next_sunday(day: &str) -> i8 {
    // Assign an index to each day of the week, starting with Sunday=0
    // This lets us calculate days until next Sunday easily by modulo arithmetic.
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"),
    };

    // If today is Sunday, next Sunday is 7 days away (one full week).
    // Otherwise, days until next Sunday is 7 - day_index.
    if day_index == 0 {
        7
    } else {
        7 - day_index
    }
}